def choose_move(observation):
    # Defensive access to observation fields
    agent_pos = observation.get('agent_position', (0, 0))
    resources = observation.get('resources', [])
    enemies = observation.get('enemies', [])
    territory = observation.get('territory', {})

    x, y = agent_pos

    # Helper function to compute move
    def move_towards(target_pos):
        tx, ty = target_pos
        dx = tx - x
        dy = ty - y
        # normalize to -1, 0, 1
        if dx != 0:
            dx = int(dx / abs(dx))
        if dy != 0:
            dy = int(dy / abs(dy))
        return max(-1, min(1, dx)), max(-1, min(1, dy))

    # Prioritize resource collection
    if resources:
        closest_resource = min(resources, key=lambda r: abs(r[0] - x) + abs(r[1] - y))
        return list(move_towards(closest_resource))

    # Then pursuit of enemies
    if enemies:
        closest_enemy = min(enemies, key=lambda e: abs(e[0] - x) + abs(e[1] - y))
        return list(move_towards(closest_enemy))

    # Then territory control: move towards owned territory if known
    my_territory = territory.get('owner', None)
    if my_territory:
        owned_positions = [pos for pos, owner in territory.items() if owner == my_territory]
        if owned_positions:
            closest_pos = min(owned_positions, key=lambda p: abs(p[0] - x) + abs(p[1] - y))
            return list(move_towards(closest_pos))

    # Default: stay in place
    return [0, 0]

